/bin/bash -lc "cd [workspace path] && python -c \"
import numpy as np
d = np.load('source_pixels.npz')['rgb'].astype(int)
bg = np.median(d, axis=0)
def show(t, x0,x1,y0,y1):
    f=d[t]; m=np.abs(f-bg).sum(2)>70
    print('frame',t)
    for y in range(y0,y1):
        cells=[]
        for x in range(x0,x1):
            if m[y,x]: cells.append('X%3d,%3d,%3d'%tuple(f[y,x]))
            else: cells.append(' .')
        print(y, ' '.join(cells))
show(9,128,142,7,18)
show(9,164,174,45,53)
\""
